	for _, hook := range gitHookNames {
		lefthookContent := "#!/bin/sh\n# lefthook managed hook\ncall_lefthook \"" + hook + "\" \"$@\"\n"
		if err := os.WriteFile(filepath.Join(hooksDir, hook), []byte(lefthookContent), 0o755); err != nil {
