func TestInstallGitHook_SelfHealAfterThirdPartyOverwrite(t *testing.T) {
	_, hooksDir := initHooksTestRepo(t)

	// Install Entire hooks initially
	_, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("initial InstallGitHook() error = %v", err)
	}

	// Simulate lefthook overwriting all hooks
	lefthookContents := make(map[string]string)
	for _, hook := range gitHookNames {
		content := "#!/bin/sh\n# lefthook managed hook\ncall_lefthook \"" + hook + "\" \"$@\"\n"
		lefthookContents[hook] = content
		if err := os.WriteFile(filepath.Join(hooksDir, hook), []byte(content), 0o755); err != nil {
			t.Fatalf("failed to overwrite %s: %v", hook, err)
		}
	}

	// Verify hooks are detected as missing
	if IsGitHookInstalled() {
		t.Fatal("hooks should not be detected as installed after overwrite")
	}

	// Self-heal: reinstall with silent=true (as the session start code does)
	count, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("self-heal InstallGitHook() error = %v", err)
	}
	if count == 0 {
		t.Error("self-heal should install hooks (count > 0)")
	}

	// Hooks should now be detected as installed
	if !IsGitHookInstalled() {
		t.Error("hooks should be installed after self-heal")
	}

	// Each hook should contain the Entire marker AND chain to the lefthook backup
	for _, hook := range gitHookNames {
		data, err := os.ReadFile(filepath.Join(hooksDir, hook))
		if err != nil {
			t.Fatalf("hook %s should exist: %v", hook, err)
		}
		hookContent := string(data)

		if !strings.Contains(hookContent, entireHookMarker) {
			t.Errorf("hook %s should contain Entire marker after self-heal", hook)
		}
		if !strings.Contains(hookContent, chainComment) {
			t.Errorf("hook %s should chain to overwritten hook after self-heal", hook)
		}

		// Lefthook content should be backed up
		backupData, err := os.ReadFile(filepath.Join(hooksDir, hook+backupSuffix))
		if err != nil {
			t.Fatalf("backup for %s should exist after self-heal: %v", hook, err)
		}
		if string(backupData) != lefthookContents[hook] {
			t.Errorf("backup for %s should contain lefthook content, got %q", hook, string(backupData))
		}
	}
}

func TestInstallGitHook_SelfHealAfterPartialOverwrite(t *testing.T) {
	_, hooksDir := initHooksTestRepo(t)

	// Install Entire hooks initially
	_, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("initial InstallGitHook() error = %v", err)
	}

	// Simulate lefthook overwriting only post-commit and pre-push
	overwritten := map[string]string{
		"post-commit": "#!/bin/sh\n# lefthook\ncall_lefthook post-commit\n",
		"pre-push":    "#!/bin/sh\n# lefthook\ncall_lefthook pre-push\n",
	}
	for hook, content := range overwritten {
		if err := os.WriteFile(filepath.Join(hooksDir, hook), []byte(content), 0o755); err != nil {
			t.Fatalf("failed to overwrite %s: %v", hook, err)
		}
	}

	// Self-heal
	count, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("self-heal InstallGitHook() error = %v", err)
	}
	// Only the two overwritten hooks should need reinstalling
	if count != 2 {
		t.Errorf("self-heal installed %d hooks, want 2 (only overwritten ones)", count)
	}

	// All hooks should now be installed
	if !IsGitHookInstalled() {
		t.Error("all hooks should be installed after self-heal")
	}

	// Overwritten hooks should have backups and chains
	for hook, originalContent := range overwritten {
		data, err := os.ReadFile(filepath.Join(hooksDir, hook))
		if err != nil {
			t.Fatalf("hook %s should exist: %v", hook, err)
		}
		if !strings.Contains(string(data), chainComment) {
			t.Errorf("overwritten hook %s should have chain call", hook)
		}

		backupData, err := os.ReadFile(filepath.Join(hooksDir, hook+backupSuffix))
		if err != nil {
			t.Fatalf("backup for %s should exist: %v", hook, err)
		}
		if string(backupData) != originalContent {
			t.Errorf("backup for %s = %q, want %q", hook, string(backupData), originalContent)
		}
	}

	// Non-overwritten hooks should NOT have backups or chains
	untouched := []string{"prepare-commit-msg", "commit-msg"}
	for _, hook := range untouched {
		backupPath := filepath.Join(hooksDir, hook+backupSuffix)
		if _, err := os.Stat(backupPath); !os.IsNotExist(err) {
			t.Errorf("untouched hook %s should NOT have a backup", hook)
		}

		data, err := os.ReadFile(filepath.Join(hooksDir, hook))
		if err != nil {
			t.Fatalf("hook %s should exist: %v", hook, err)
		}
		if strings.Contains(string(data), chainComment) {
			t.Errorf("untouched hook %s should NOT have chain call", hook)
		}
	}
}

func TestInstallGitHook_SelfHealAfterHooksDeleted(t *testing.T) {
	_, hooksDir := initHooksTestRepo(t)

	// Install Entire hooks initially
	_, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("initial InstallGitHook() error = %v", err)
	}

	// Simulate third-party tool deleting all hooks
	for _, hook := range gitHookNames {
		if err := os.Remove(filepath.Join(hooksDir, hook)); err != nil {
			t.Fatalf("failed to delete %s: %v", hook, err)
		}
	}

	if IsGitHookInstalled() {
		t.Fatal("hooks should not be detected after deletion")
	}

	// Self-heal
	count, err := InstallGitHook(true)
	if err != nil {
		t.Fatalf("self-heal InstallGitHook() error = %v", err)
	}
	if count != len(gitHookNames) {
		t.Errorf("self-heal installed %d hooks, want %d", count, len(gitHookNames))
	}

	if !IsGitHookInstalled() {
		t.Error("hooks should be installed after self-heal")
	}

	// No backups should exist (there was nothing to back up)
	for _, hook := range gitHookNames {
		backupPath := filepath.Join(hooksDir, hook+backupSuffix)
		if _, err := os.Stat(backupPath); !os.IsNotExist(err) {
			t.Errorf("backup for %s should not exist (hook was deleted, not replaced)", hook)
		}
	}
