		t.Fatalf("backup should contain original content")
	}

	// Simulate lefthook overwriting entire hook (but backup is still there)
	lefthookContent := "#!/bin/sh\n# lefthook managed\ncall_lefthook prepare-commit-msg\n"
	if err := os.WriteFile(hookPath, []byte(lefthookContent), 0o755); err != nil {
		t.Fatalf("failed to overwrite with lefthook: %v", err)
	}

	// Self-heal reinstall
	_, err = InstallGitHook(true)
	if err != nil {
		t.Fatalf("self-heal InstallGitHook() error = %v", err)
	}

	// The ORIGINAL user backup should be preserved (not overwritten with lefthook content)
	backupData, err = os.ReadFile(backupPath)
	if err != nil {
		t.Fatalf("backup should still exist: %v", err)
	}
	if string(backupData) != originalContent {
		t.Errorf("original backup should be preserved, got %q, want %q", string(backupData), originalContent)
	}

	// Hook should be reinstalled with chain
	hookData, err := os.ReadFile(hookPath)
	if err != nil {
		t.Fatalf("hook should exist: %v", err)
	}
	if !strings.Contains(string(hookData), entireHookMarker) {
		t.Error("hook should contain Entire marker")
	}
	if !strings.Contains(string(hookData), chainComment) {
		t.Error("hook should chain to backup")
	}
}

